mapper.select:
SELECT distinct a.IND_ID indId, a.IND_NAME indName, a.IND_YPE indType, a.REMARK remark FROM STT_INDICATOR a LEFT JOIN STT_INDICATOR_SUIT b ON a.IND_ID=b.IND_ID WHERE 1=1
AND b.PARAM_CODE = #{paramCode, jdbcType=VARCHAR}
AND b.PARAM_VALUE = #{paramValue, jdbcType=VARCHAR}
AND a.IND_YPE = #{indType, jdbcType=VARCHAR}

select f.ftrId, f.ftrName, f.remark from STT_SCENE_FACTOR sttSceFac right join (SELECT e.ftr_id ftrId, e.ftr_name ftrName, e.remark FROM ( SELECT a.ftr_id, a.ftr_name, a.remark, b.tips_value as rskType, c.tips_value as rskType2 FROM STT_FACTOR a left join STT_FACTOR_tips b on a.ftr_id = b.ftr_id and b.dict_code ='FTR_RSK_TYPE'
left join STT_FACTOR_tips c on a.ftr_id = c.ftr_id and c.dict_code='FTR_RSK_TYPE_02'
)e
AND e.rskType =#{rskType, jdbcType=VARCHAR}
AND e.rskType2=#{rskType2, jdbcType=VARCHAR}
)f ON sttSceFac.ftr_id = f.ftrId
AND sttSceFac.scene_id=#{sceneId, jdbcType=VARCHAR}

select 
	e.tmpl_id tmplId,
	e.tmpl_name tmplName
	from 
	(select a.tmpl_id,a.tmpl_name ,tip1.tips_value sceneType,tip2.tips_value riskType
	from stt_stress_tmpl a 
	left join stt_stress_tips tip1 on a.tmpl_id = tip1.tmpl_id

		and tip1.dict_code=#{sceneType, jdbcType=VARCHAR}

	left join stt_stress_tips tip2 on a.tmpl_id = tip2.tmpl_id

		and tip2.dict_code=#{riskType, jdbcType=VARCHAR}

	)e	


			and e.sceneType=#{sceneTypeCode, jdbcType=VARCHAR}


			and e.riskType=#{riskTypeCode, jdbcType=VARCHAR}

select ind_id indId,ind_name indName,remark from( select case when ind_id='1003' then 1 when ind_id='1009' then 2 when ind_id='1004' then 3 when ind_id='1005' then 4 when ind_id='1006' then 5 when ind_id='1001' then 1 when ind_id='1002' then 2 when ind_id='1007' then 3 when ind_id='1008' then 4 end as orderId, ind_id, ind_name, remark from (select a.ind_Id, b.ind_name, b.remark from stt_stress_indicator a left JOIN stt_indicator b on a.ind_id=b.ind_id
and a.model_id=#{modelId, jdbcType=VARCHAR}
and b.ind_ype=#{indType, jdbcType=VARCHAR}
and a.STT_BUSI_TYPE=#{sttBusiType, jdbcType=VARCHAR}
))order by orderId asc

SELECT e.remark, d.scene_id sceneId, d.ftr_id ftrId, e.ftr_name as ftrName, m.SCENE_FTR_ID sceneFtrId, m.LIGHT_VALUE lightValue, m.MEDIUM_VALUE mediumValue, m.HEAVY_VALUE heavyValue FROM stt_scene_factor d LEFT JOIN stt_factor e ON d.ftr_id = e.ftr_id LEFT JOIN STT_SCENE_LMH m ON d.ftr_id = m.ftr_id and d.scene_id = m.scene_id
and d.SCENE_ID=#{sceneId, jdbcType=VARCHAR}
and e.ftr_id in (select ftr_id from stt_factor_tips where dict_code='FTR_RSK_TYPE_02' and tips_value=#{tipsValue, jdbcType=VARCHAR})

SELECT PARAM_CODE paramCode, PARAM_VALUE paramValue, SCENE_FTRTIPS_ID sceneFtrtipsId FROM STT_SCENE_FTRTIPS
and SCENE_ID=#{sceneId, jdbcType=VARCHAR}
and DICT_CODE=#{dictCode, jdbcType=VARCHAR}

select a.tips_value sceneType2, b.tips_value openmode from ( select tips.tips_value,sce.SCENE_ID from stt_scene sce left join stt_Scene_Tips tips on sce.SCENE_ID= tips.SCENE_ID
and sce.SCENE_ID=#{sceneId, jdbcType=VARCHAR}
and tips.dict_code='SCENE_TYPE2')a left JOIN ( select tips.tips_value, sce.SCENE_ID from stt_scene sce left join stt_Scene_Tips tips on sce.SCENE_ID= tips.SCENE_ID
and sce.SCENE_ID=#{sceneId, jdbcType=VARCHAR}
and tips.dict_code='OPENMODE')b on a.scene_id=b.scene_id
